// GEMM dimensions are specific to F(2x2,3x3): M=128, N=64, K=16 or 128.
static void gemmPortable(const float* a, const float* b, float* c, int kCount) {
    std::fill(c, c + 128 * 64, 0.0f);
    for (int m = 0; m < 128; ++m)
        for (int k = 0; k < kCount; ++k) {
            float w = a[m * kCount + k];
            for (int n = 0; n < 64; ++n)
                c[m * 64 + n] += w * b[k * 64 + n];
        }
}

#if defined(__x86_64__) || defined(__i386__)
__attribute__((target("avx2,fma")))
static void gemmAvx2(const float* a, const float* b, float* c, int kCount) {
    for (int m = 0; m < 128; m += 4)
        for (int n = 0; n < 64; n += 16) {
            __m256 c00 = _mm256_setzero_ps(), c01 = c00;
            __m256 c10 = c00, c11 = c00, c20 = c00, c21 = c00, c30 = c00, c31 = c00;
            for (int k = 0; k < kCount; ++k) {
                __m256 b0 = _mm256_loadu_ps(b + k * 64 + n);
                __m256 b1 = _mm256_loadu_ps(b + k * 64 + n + 8);
                __m256 w = _mm256_set1_ps(a[(m + 0) * kCount + k]);
                c00 = _mm256_fmadd_ps(w, b0, c00); c01 = _mm256_fmadd_ps(w, b1, c01);
                w = _mm256_set1_ps(a[(m + 1) * kCount + k]);
                c10 = _mm256_fmadd_ps(w, b0, c10); c11 = _mm256_fmadd_ps(w, b1, c11);
                w = _mm256_set1_ps(a[(m + 2) * kCount + k]);
                c20 = _mm256_fmadd_ps(w, b0, c20); c21 = _mm256_fmadd_ps(w, b1, c21);
                w = _mm256_set1_ps(a[(m + 3) * kCount + k]);
                c30 = _mm256_fmadd_ps(w, b0, c30); c31 = _mm256_fmadd_ps(w, b1, c31);
            }
            _mm256_storeu_ps(c + (m + 0) * 64 + n, c00); _mm256_storeu_ps(c + (m + 0) * 64 + n + 8, c01);
            _mm256_storeu_ps(c + (m + 1) * 64 + n, c10); _mm256_storeu_ps(c + (m + 1) * 64 + n + 8, c11);
            _mm256_storeu_ps(c + (m + 2) * 64 + n, c20); _mm256_storeu_ps(c + (m + 2) * 64 + n + 8, c21);
            _mm256_storeu_ps(c + (m + 3) * 64 + n, c30); _mm256_storeu_ps(c + (m + 3) * 64 + n + 8, c31);
        }
}
#endif

using Gemm = void (*)(const float*, const float*, float*, int);
struct Layer {
    int inputs, outputs, size;
    std::vector<float> kernel, scale, offset;
};

static std::vector<float> decodeWeights() {
    std::array<int, 256> table;
    table.fill(-1);
    const std::string alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    for (int i = 0; i < 64; ++i) table[static_cast<unsigned char>(alphabet[i])] = i;
    std::vector<unsigned char> bytes;
    bytes.reserve(sizeof(WEIGHTS_B64) * 3 / 4);
    uint32_t accumulator = 0;
    int bits = 0;
    for (const unsigned char* p = reinterpret_cast<const unsigned char*>(WEIGHTS_B64); *p; ++p) {
        int v = table[*p];
        if (v < 0) continue;
        accumulator = (accumulator << 6) | static_cast<uint32_t>(v);
        bits += 6;
        if (bits >= 8) { bits -= 8; bytes.push_back(static_cast<unsigned char>(accumulator >> bits)); }
    }
    if (bytes.size() % sizeof(float)) throw std::runtime_error("Invalid weights");
    std::vector<float> result(bytes.size() / sizeof(float));
    std::memcpy(result.data(), bytes.data(), bytes.size());
    return result;
}

class PolicyModel {
    std::vector<Layer> layers;
    std::vector<float> linear, bias;
    std::vector<float> v, products, trunk, hidden1, hidden2, policy;
    Gemm gemm = gemmPortable;

    void convolution(const float* x, const Layer& layer, float* out, const float* residual = nullptr) {
        int channels = layer.inputs;
        if (layer.size == 1) {
            for (int o = 0; o < layer.outputs; ++o)
                for (int pos = 0; pos < 256; ++pos) {
                    float sum = 0;
                    for (int c = 0; c < channels; ++c) sum += layer.kernel[o * channels + c] * x[c * 256 + pos];
                    sum *= layer.scale[o]; sum += layer.offset[o];
                    out[o * 256 + pos] = std::max(0.0f, sum);
                }
            return;
        }
        // B^T d B, writing directly to the persistent 16xCx64 matrix.
        for (int c = 0; c < channels; ++c)
            for (int tile = 0; tile < 64; ++tile) {
                float d[4][4], t[4][4], z[4][4];
                int row = 2 * (tile / 8) - 1, column = 2 * (tile % 8) - 1;
                for (int i = 0; i < 4; ++i)
                    for (int j = 0; j < 4; ++j) {
                        int r = row + i, col = column + j;
                        d[i][j] = (r >= 0 && r < 16 && col >= 0 && col < 16) ? x[c * 256 + r * 16 + col] : 0.0f;
                    }
                for (int j = 0; j < 4; ++j) {
                    t[0][j] = d[0][j] - d[2][j]; t[1][j] = d[1][j] + d[2][j];
                    t[2][j] = d[2][j] - d[1][j]; t[3][j] = d[1][j] - d[3][j];
                }
                for (int i = 0; i < 4; ++i) {
                    z[i][0] = t[i][0] - t[i][2]; z[i][1] = t[i][1] + t[i][2];
                    z[i][2] = t[i][2] - t[i][1]; z[i][3] = t[i][1] - t[i][3];
                    for (int j = 0; j < 4; ++j) v[((i * 4 + j) * channels + c) * 64 + tile] = z[i][j];
                }
            }
        for (int t = 0; t < 16; ++t)
            gemm(layer.kernel.data() + t * 128 * channels, v.data() + t * channels * 64,
                 products.data() + t * 128 * 64, channels);
        for (int o = 0; o < 128; ++o)
            for (int tile = 0; tile < 64; ++tile) {
                float a[2][4];
                for (int j = 0; j < 4; ++j) {
                    float m0 = products[((0 * 4 + j) * 128 + o) * 64 + tile];
                    float m1 = products[((1 * 4 + j) * 128 + o) * 64 + tile];
                    float m2 = products[((2 * 4 + j) * 128 + o) * 64 + tile];
                    float m3 = products[((3 * 4 + j) * 128 + o) * 64 + tile];
                    a[0][j] = (m0 + m1) + m2; a[1][j] = (m1 - m2) - m3;
                }
                for (int i = 0; i < 2; ++i) {
                    float y[2] = {(a[i][0] + a[i][1]) + a[i][2], (a[i][1] - a[i][2]) - a[i][3]};
                    for (int j = 0; j < 2; ++j) {
                        int index = o * 256 + (2 * (tile / 8) + i) * 16 + 2 * (tile % 8) + j;
                        float value = y[j] * layer.scale[o]; value += layer.offset[o];
                        if (residual) value += residual[index];
                        out[index] = std::max(0.0f, value);
                    }
                }
            }
    }

public:
    explicit PolicyModel(bool useAvx = true) : v(16 * 128 * 64), products(16 * 128 * 64), trunk(128 * 256),
                    hidden1(128 * 256), hidden2(128 * 256), policy(2 * 256) {
#if defined(__x86_64__) || defined(__i386__)
        if (useAvx && __builtin_cpu_supports("avx2") && __builtin_cpu_supports("fma")) gemm = gemmAvx2;
#endif
        auto raw = decodeWeights();
        size_t cursor = 0;
        auto take = [&](size_t count) {
            if (cursor + count > raw.size()) throw std::runtime_error("Truncated weights");
            std::vector<float> values(raw.begin() + cursor, raw.begin() + cursor + count);
            cursor += count; return values;
        };
        for (int index = 0; index < 22; ++index) {
            Layer layer;
            layer.inputs = index == 0 ? 16 : 128;
            layer.outputs = index == 21 ? 2 : 128;
            layer.size = index == 21 ? 1 : 3;
            auto kernel = take(layer.outputs * layer.inputs * layer.size * layer.size);
            layer.scale = take(layer.outputs); layer.offset = take(layer.outputs);
            if (layer.size == 1) layer.kernel = std::move(kernel);
            else {
                layer.kernel.resize(16 * layer.outputs * layer.inputs);
                for (int o = 0; o < layer.outputs; ++o)
                    for (int c = 0; c < layer.inputs; ++c) {
                        const float* k = kernel.data() + (o * layer.inputs + c) * 9;
                        float a[4][3], u[4][4];
                        for (int j = 0; j < 3; ++j) {
                            a[0][j] = k[j]; a[1][j] = (0.5f*k[j] + 0.5f*k[3+j]) + 0.5f*k[6+j];
                            a[2][j] = (0.5f*k[j] - 0.5f*k[3+j]) + 0.5f*k[6+j]; a[3][j] = k[6+j];
                        }
                        for (int i = 0; i < 4; ++i) {
                            u[i][0] = a[i][0]; u[i][1] = (0.5f*a[i][0] + 0.5f*a[i][1]) + 0.5f*a[i][2];
                            u[i][2] = (0.5f*a[i][0] - 0.5f*a[i][1]) + 0.5f*a[i][2]; u[i][3] = a[i][2];
                            for (int j = 0; j < 4; ++j) layer.kernel[((i*4+j)*layer.outputs+o)*layer.inputs+c] = u[i][j];
                        }
                    }
            }
            layers.push_back(std::move(layer));
        }
        linear = take(256 * 512); bias = take(256);
        if (cursor != raw.size()) throw std::runtime_error("Unexpected weights");
    }

    std::array<float, 256> forward(const std::array<float, 4096>& features) {
        convolution(features.data(), layers[0], trunk.data());
        for (int block = 0; block < 10; ++block) {
            convolution(trunk.data(), layers[1 + block * 2], hidden1.data());
            convolution(hidden1.data(), layers[2 + block * 2], hidden2.data(), trunk.data());
            trunk.swap(hidden2);
        }
        convolution(trunk.data(), layers[21], policy.data());
        std::array<float, 256> logits;
        for (int i = 0; i < 256; ++i) {
            float sum = 0.0f;
            for (int j = 0; j < 512; ++j) sum += linear[i * 512 + j] * policy[j];
            logits[i] = sum + bias[i];
        }
        return logits;
    }
};

static std::array<float, 4096> encodeFeatures(const std::array<int, 256>& board,
        const std::vector<int>& history, int side, const std::vector<int>& legal) {
    std::array<float, 4096> features{};
    for (int a = 0; a < 256; ++a) {
        features[a] = board[a] == 1; features[256 + a] = board[a] == -1;
        features[3 * 256 + a] = side == 1;
    }
    for (int a : legal) features[2 * 256 + a] = 1;
    auto historical = board;
    for (int offset = 0; offset < 4; ++offset) {
        if (offset < static_cast<int>(history.size())) historical[history[history.size()-offset-1]] = 0;
        for (int a = 0; a < 256; ++a) {
            features[(4 + offset * 2) * 256 + a] = historical[a] == 1;
            features[(5 + offset * 2) * 256 + a] = historical[a] == -1;
        }
    }
    bool blue = false, orange = false;
    for (auto it = history.rbegin(); it != history.rend(); ++it) {
        int a = *it;
        if (board[a] == 1 && !blue) { features[12 * 256 + a] = 1; blue = true; }
        if (board[a] == -1 && !orange) { features[13 * 256 + a] = 1; orange = true; }
        if (blue && orange) break;
    }
    const float step = 2.0f / 15.0f;
    for (int a = 0; a < 256; ++a) {
        int row = a / 16, col = a % 16;
        features[14 * 256 + a] = row < 8 ? -1.0f + step * row : 1.0f - step * (15-row);
        features[15 * 256 + a] = col < 8 ? -1.0f + step * col : 1.0f - step * (15-col);
    }
    return features;
}

int main(int argc, char** argv) {
    std::ios::sync_with_stdio(false); std::cin.tie(nullptr);
    auto initializedAt = std::chrono::steady_clock::now();
    std::string mode = argc > 1 ? argv[1] : "";
    PolicyModel model(mode != "--portable-logits" && mode != "--portable-bench");
    double initializationMs = std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - initializedAt).count();
    if (mode == "--bench" || mode == "--portable-bench") {
        std::array<float, 4096> features;
        for (int i = 0; i < 4096; ++i) features[i] = static_cast<float>((i * 7) % 17) / 17.0f;
        int count = argc > 2 ? std::stoi(argv[2]) : 200;
        std::vector<double> elapsed;
        volatile float checksum = 0;
        for (int i = 0; i < count; ++i) {
            auto start = std::chrono::steady_clock::now();
            auto output = model.forward(features);
            checksum += output[i % 256];
            elapsed.push_back(std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count());
        }
        double mean = 0;
        for (double value : elapsed) mean += value / count;
        std::sort(elapsed.begin(), elapsed.end());
        std::cout << "{\"initialization_ms\":" << initializationMs << ",\"mean_ms\":" << mean
                  << ",\"p99_ms\":" << elapsed[static_cast<size_t>(0.99 * (count-1))]
                  << ",\"maximum_ms\":" << elapsed.back() << ",\"iterations\":" << count << "}" << std::endl;
        return 0;
    }
    if (mode == "--logits" || mode == "--portable-logits") {
        std::array<float, 4096> features;
        while (std::cin >> features[0]) {
            for (int i = 1; i < 4096; ++i) if (!(std::cin >> features[i])) return 1;
            auto logits = model.forward(features);
            std::cout << std::setprecision(9);
            for (float value : logits) std::cout << value << ' ';
            std::cout << std::endl;
        }
        return 0;
    }
    std::array<std::vector<int>, 3> histories;
    std::array<std::array<int, 256>, 3> known{};
    int game, ply, myScore, opponentScore;
    std::string color;
    while (std::cin >> game >> color >> ply >> myScore >> opponentScore) {
        if (game < 1 || game > 2) return 1;
        int side = color == "B" ? 1 : 2;
        std::array<int, 256> board{};
        std::string row;
        for (int r = 0; r < 16; ++r) {
            if (!(std::cin >> row) || row.size() != 16) return 1;
            for (int c = 0; c < 16; ++c) board[r*16+c] = row[c] == 'B' ? 1 : row[c] == 'O' ? -1 : 0;
        }
        int count; if (!(std::cin >> count) || count < 1 || count > 256) return 1;
        std::vector<int> legal(count);
        for (int& action : legal) if (!(std::cin >> action) || action < 0 || action >= 256) return 1;
        auto& history = histories[game];
        int added = 0;
        for (int a = 0; a < 256; ++a) if (board[a] != known[game][a]) {
            if (!board[a] || known[game][a]) return 1;
            history.push_back(a); ++added;
        }
        if (added > 1 || static_cast<int>(history.size()) != ply) return 1;
        auto features = encodeFeatures(board, history, side, legal);
        if (mode == "--features") {
            std::cout << std::setprecision(9);
            for (float value : features) std::cout << value << ' ';
            std::cout << std::endl;
        }
        auto logits = model.forward(features);
        int action = legal[0];
        for (int candidate : legal) if (logits[candidate] > logits[action]) action = candidate;
        board[action] = side == 1 ? 1 : -1;
        history.push_back(action); known[game] = board;
        std::cout << action << std::endl;
    }
}
